// button topic: "befehl" oder "befehl:kanal", z.B. "volumeUp:2", "gain:all"
const [cmd, ch] = String(msg.topic || "").split(":");
msg.topic = cmd;
if (ch !== undefined) msg.channel = ch === "all" ? "all" : +ch;
return msg;

msg.payload = "Fehler: " + (msg.error && msg.error.message);
msg.ui_update = { color: "#c62828" };
return msg;

if (msg.topic !== "status") return null;
const s = msg.payload;
const info = [
    { Eigenschaft: "Modell", Wert: s.info.model }, { Eigenschaft: "Seriennummer", Wert: s.info.serial },
    { Eigenschaft: "Firmware", Wert: s.info.firmware }, { Eigenschaft: "MAC", Wert: s.info.mac },
    { Eigenschaft: "Nickname", Wert: s.nickname }, { Eigenschaft: "IP", Wert: s.network.ip },
    { Eigenschaft: "Netzmaske", Wert: s.network.netmask }, { Eigenschaft: "Gateway", Wert: s.network.gateway },
    { Eigenschaft: "GPO-Relais", Wert: s.gpoRelayClosed ? "geschlossen" : "offen" }];
const alarm = [
    { Alarm: "Lüfter", Zustand: (s.alarms.fan ? "⚠ ALARM" : "OK") },
    { Alarm: "Übertemperatur (>95 °C)", Zustand: (s.alarms.highOverTemperature ? "⚠ ALARM" : "OK") },
    { Alarm: "Netzteil-Temperatur", Zustand: (s.alarms.psTemperature ? "⚠ ALARM" : "OK") },
    { Alarm: "Hilfsspannung (Aux)", Zustand: (s.alarms.vaux ? "⚠ ALARM" : "OK") },
    { Alarm: "Generic Fault", Zustand: (s.alarms.genericFault ? "⚠ ALARM" : "OK") },
    { Alarm: "Aktive Faults", Zustand: s.alarms.faults.length ? s.alarms.faults.join(", ") : "keine" }];
const ch = [0, 1, 2, 3].map(i => ({ Kanal: i + 1,
    "SOA thermisch": (s.alarms.soaThermal[i] ? "⚠ ALARM" : "OK"), Temperatur: (s.alarms.temperature[i] ? "⚠ ALARM" : "OK"),
    "V-Rail": (s.alarms.vrail[i] ? "⚠ ALARM" : "OK"),
    "Schutz-Mute": s.alarms.protectionMutes[i].length ? s.alarms.protectionMutes[i].join(", ") : "–" }));
// only send when something changed
const out = [info, alarm, ch].map((p, i) => { const k = JSON.stringify(p); if (context.get("t" + i) === k) return null;
    context.set("t" + i, k); return { payload: p }; });
return out;

if (msg.topic === "status") {
    const s = msg.payload;
    const t = [["Trafo", s.supply.tempTransformer], ["Kühlkörper", s.supply.tempHeatsink]]
        .concat(s.channelTemp.map((v, i) => ["CH" + (i + 1), v]))
        .map(([topic, payload]) => ({ topic, payload }));
    return [t, { topic: "Netz", payload: s.supply.mainsVrms }, null];
}
if (msg.topic === "meters") {
    return [null, null, msg.payload.output.vRms.map((v, i) => ({ topic: "CH" + (i + 1), payload: v }))];
}
return null;

const prev = context.get("prev") || {};
let txt = null, color = "#0d74ce";
if (msg.topic === "connection") {
    if (prev.connected !== undefined && prev.connected !== msg.payload.connected) {
        txt = msg.payload.connected ? "Verbindung zum Mezzo wiederhergestellt" : "Verbindung zum Mezzo verloren: " + (msg.payload.error || "");
        color = msg.payload.connected ? "#2e7d32" : "#c62828";
    }
    prev.connected = msg.payload.connected;
} else if (msg.topic === "status") {
    const a = msg.payload.alarms;
    if (prev.any === false && a.any) { txt = "ALARM Mezzo: " + a.fault + (a.faults.length ? " (" + a.faults.join(", ") + ")" : ""); color = "#c62828"; }
    if (prev.any === true && !a.any) { txt = "Mezzo: Alarm behoben"; color = "#2e7d32"; }
    if (prev.standby !== undefined && prev.standby !== msg.payload.standby) txt = msg.payload.standby ? "Mezzo im Standby" : "Mezzo eingeschaltet";
    prev.any = a.any; prev.standby = msg.payload.standby;
}
context.set("prev", prev);
if (!txt) return null;
return { payload: txt, ui_update: { color } };
